CREATE TABLE dsh_session_binding (id CHAR(36) NOT NULL PRIMARY KEY,legacy_id BIGINT,owner_id BIGINT NOT NULL,dsh_session_id VARCHAR(128) NOT NULL,workspace_key VARCHAR(64) NOT NULL,status VARCHAR(32) NOT NULL,last_sequence BIGINT NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,CONSTRAINT uk_dsh_session UNIQUE(dsh_session_id),CONSTRAINT uk_dsh_legacy UNIQUE(legacy_id));
CREATE INDEX idx_dsh_owner_updated ON dsh_session_binding(owner_id,updated_at);
CREATE TABLE dsh_session_migration (legacy_id BIGINT NOT NULL PRIMARY KEY,migration_key VARCHAR(128) NOT NULL,payload_sha256 CHAR(64) NOT NULL,binding_id CHAR(36) NOT NULL,imported_at TIMESTAMP(6) NOT NULL,CONSTRAINT fk_dsh_migration_binding FOREIGN KEY(binding_id) REFERENCES dsh_session_binding(id));
